entries[30331] = { ["name"] = "Zanzas ewiger Glanz", ["text"] = "100 Meter Reichweite\nSofort\nErhöht die Chance, feindliche Zauber zu reflektieren, um 3%. Hält 2 Stunden lang an. Der erste Angriffszauber gegen den Nutzer wird automatisch reflektiert. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein." }
