entries[30334] = { ["name"] = "Geeichtes Eterniumzielfernrohr", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärtetes Adamantitrohr (2), Teufelsstahlstabilisator (6), Stern der Elune (2)\nGeeichtes Eterniumzielfernrohr\n60\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht die kritische Trefferwertung dieser Waffe um 28.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[30336] = { ["name"] = "Zanzas ewiger Geist", ["text"] = "100 Meter Reichweite\nSofort\nErhöht 2 Stunden lang die Willenskraft des Spielers um 50 und die Ausdauer um 50. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein." }
entries[30337] = { ["name"] = "Krachbummroboter", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nAdamantitrahmen , Teufelseisengehäuse (2), Goldkraftkern , Eine Hand voll Teufelseisenbolzen (2)\nKrachbummroboter\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Rechtsklicken, um einen robotischen Begleiter zu beschwören, der gegen andere Roboter kämpfen wird. (3 Min Abklingzeit)" }
entries[30338] = { ["name"] = "Zanzas ewige Schnelligkeit", ["text"] = "100 Meter Reichweite\nSofort\nErhöht das Lauftempo des Spielers 2 Stunden lang um 20%. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein." }
entries[30341] = { ["name"] = "Weißes Rauchsignal", ["text"] = "Wirken in 2 sek.\nReagenzien:\nElementarsprengpulver , Netherstoff\n(3)\nBenutzen: Wirft ein weißes Rauchsignal in ein bestimmtes Gebiet. Hält 5 Min. lang an. (5 Sek. Abklingzeit)" }
entries[30342] = { ["name"] = "Rotes Rauchsignal", ["text"] = "Wirken in 2 sek.\nReagenzien:\nElementarsprengpulver , Netherstoff , Roter Farbstoff" }
entries[30343] = { ["name"] = "Blaues Rauchsignal", ["text"] = "Wirken in 2 sek.\nReagenzien:\nElementarsprengpulver , Netherstoff , Blauer Farbstoff" }
entries[30344] = { ["name"] = "Grünes Rauchsignal", ["text"] = "Wirken in 2 sek.\nReagenzien:\nElementarsprengpulver , Netherstoff , Grüner Farbstoff\n(3)\nBenutzen: Wirft ein grünes Rauchsignal in ein bestimmtes Gebiet. Hält 5 Min. lang an. (5 Sek. Abklingzeit)" }
entries[30348] = { ["name"] = "Werkzeugkasten aus Teufelseisen", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nTeufelseisengehäuse , Teufelseisenbarren (5), Eine Hand voll Teufelseisenbolzen (2)\nWerkzeugkasten aus Teufelseisen\nWird beim Anlegen gebunden\n24 Platz Ingenieurstasche" }
entries[30349] = { ["name"] = "Werkzeugkasten aus Titan", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSaronitbarren (8), Titanbarren (8), Eine Hand voll Kobaltbolzen (4)\nWerkzeugkasten aus Titan\nWird beim Anlegen gebunden\n32 Platz Ingenieurstasche\n\"Unterteilt in kleine Fächer, die sich perfekt für die Aufbewahrung von Ingenieursbedarf eignen.\"" }
