entries[30551] = { ["name"] = "Heiltrankeinspritzung", ["text"] = "Wirken in 25 sek.\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nTeufelseisengehäuse , Eine Hand voll Teufelseisenbolzen , Knotenhautleder (2), Erstklassiger Heiltrank (20)\n(20)\n55\nBenutzen: Stellt 1500 to 2500 Gesundheit wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)" }
entries[30552] = { ["name"] = "Manatrankeinspritzung", ["text"] = "Wirken in 25 sek.\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nTeufelseisengehäuse , Eine Hand voll Teufelseisenbolzen , Knotenhautleder (2), Erstklassiger Manatrank (20)\n(20)\n55\nBenutzen: Stellt 1800 to 3000 Mana wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)" }
