entries[30554] = { ["name"] = "Zorn der Titanen", ["text"] = "30 Meter Reichweite\nSofort\nEure offensiven Fähigkeiten fügen zusätzlichen Elementarschaden zu. Jede Fähigkeit verbraucht 1 Aufladung." }
entries[30555] = { ["name"] = "Tragbarer Briefkasten", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nAdamantitrahmen , Eine Hand voll Teufelseisenbolzen (2), Khoriumkraftkern , Verschmorte Verkabelung" }
entries[30556] = { ["name"] = "Raketenstiefel Xtrem", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchweres Knotenhautleder (8), Khoriumkraftkern (2), Gehärtetes Adamantitrohr (2), Teufelsstahlstabilisator (4)\nRaketenstiefel Xtrem\nWird beim Anlegen gebunden\nFüße Leder\n350 Rüstung\n+40 Beweglichkeit\nHaltbarkeit 65 / 65\nBenötigt Ingenieurskunst\n(330)\nBenutzen: Die Raketenstiefel aktivieren, um einen gewaltigen Geschwindigkeitsschub zu erhalten. (5 Min Abklingzeit)" }
entries[30557] = { ["name"] = "Zorn der Titanen", ["text"] = "Sofort\nBricht das Siegel des Buches und gewährt Euren offensiven Zaubern eine Chance, zusätzlichen Schaden zuzufügen.\n(Procchance: 3%, 30s Abklingzeit)" }
entries[30558] = { ["name"] = "Die Größere", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nTeufelseisengehäuse (3), Elementarsprengpulver (6), Arkanes Pulver (3), Eine Hand voll Teufelseisenbolzen (2)\n(3)\nBenötigt Ingenieurskunst\n(325)" }
entries[30559] = { ["name"] = "Vermächtnis des Bergkönigs", ["text"] = "Sofort\nErhöht Eure Rüstung um 8000.\nErhöht Euren Zauberwiderstand um 100." }
entries[30560] = { ["name"] = "Super Pioniersprengladung", ["text"] = "Wirken in 25 sek.\nReagenzien:\nNetherstoff (4), Elementarsprengpulver (4), Urmana\n(2)\nBenötigt Ingenieurskunst\n(340)\nBenutzen: Explodiert bei Zündung, verursacht 900 to 1500 Feuerschaden an allen in der Nähe befindlichen feindlichen Einheiten und an Euch 675 to 1125 Schaden. (5 Min Abklingzeit)" }
entries[30561] = { ["name"] = "Goblindampfpanzersteuerung", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nTeufelseisengehäuse , Eine Hand voll Teufelseisenbolzen (4), Goldkraftkern" }
entries[30562] = { ["name"] = "Vermächtnis des Bergkönigs", ["text"] = "Sofort\nBricht das Siegel des Buches und gewährt Euch eine Chance, Eure Rüstung und Euren Magiewiderstand zu erhöhen, wenn Ihr im Gefecht getroffen werdet.\n(Procchance: 3%)" }
entries[30563] = { ["name"] = "Goblinraketenwerfer", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärtetes Adamantitrohr (2), Khoriumkraftkern , Teufelsstahlstabilisator (2), Urfeuer (6), Urerde (6), Empfindlicher Arkanitwandler (2)\nGoblinraketenwerfer\nWird beim Anlegen gebunden\nSchmuck\n+45 Ausdauer\nBenötigt Ingenieurskunst\n(350)\nBenötigt Gobliningenieur\nBenutzen: Feuert eine mächtige Rakete auf den Gegner, die 960 to 1440 Schaden verursacht und ihn 3 Sek. lang betäubt. Das Ding hat aber einen ziemlichen Rückstoß... (2 Min Abklingzeit)" }
entries[30564] = { ["name"] = "Groll des Worgen", ["text"] = "Sofort\nVerwandelt den Zaubernden in einen Worgen. Dadurch fügen Nahkampf- und Distanzangriffe 200 Schattenschaden zu.\n(2s Abklingzeit)" }
entries[30565] = { ["name"] = "Verzauberter Helm des Vorarbeiters", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchattenstoff (4), Urmana (12), Urluft (12)\nVerzauberter Helm des Vorarbeiters\nWird beim Aufheben gebunden\nKopf Stoff\n279 Rüstung\n+70 Ausdauer\n+31 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Ingenieurskunst\n(350)\nBenötigt Gobliningenieur\nAnlegen: +10% Betäubungswiderstand." }
entries[30566] = { ["name"] = "Verstärkter Helm des Vorarbeiters", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärteter Adamantitbarren (8), Urerde (12), Urfeuer (12)\nVerstärkter Helm des Vorarbeiters\nWird beim Aufheben gebunden\nKopf Kette\n596 Rüstung\n+31 Beweglichkeit\n+70 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Ingenieurskunst\n(350)\nBenötigt Gobliningenieur\nAnlegen: Erhöht Eure Chance, Betäubungs- und Desorientierungseffekten zu widerstehen, um 10%." }
entries[30567] = { ["name"] = "Qual des Worgen", ["text"] = "Sofort\nBricht das Siegel des Buches und gewährt Euch eine Chance, bei Nahkampf- und Distanzangriffen zusätzlichen Schattenschaden zu verursachen." }
entries[30568] = { ["name"] = "Gnomisches Flammengeschütz", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nAdamantitrahmen , Eine Hand voll Teufelseisenbolzen (2), Elementarsprengpulver (3), Teufelseisengehäuse\n(3)\nBenötigt Ingenieurskunst\n(325)\nBenutzen: Errichtet schnell ein gnomisches Flammengeschütz zu Euren Füßen, das automatisch angreifen wird. Meistens Gegner. Das Geschütz fällt nach 45 Sek. in sich zusammen. (1 Min Abklingzeit)" }
entries[30569] = { ["name"] = "Gnomischer Geflügelisierer", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärtetes Adamantitrohr (2), Khoriumkraftkern (2), Arkaner Staub (10), Großer Prismasplitter (2)\nGnomischer Geflügelisierer\nWird beim Anlegen gebunden\nSchmuck\n+45 Ausdauer\nBenötigt Ingenieurskunst\n(340)\nBenötigt Gnomeningenieur\nBenutzen: Verwandelt den Gegner 15 Sek. lang in ein Huhn. Das heißt, falls die Transmogrifikationspolarität nicht verwechselt wurde... (5 Min Abklingzeit)" }
entries[30570] = { ["name"] = "Gürtel der fast perfekten Unverwundbarkeit", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchweres Knotenhautleder (8), Khoriumkraftkern (4), Urleben (10), Urschatten (10), Empfindlicher Arkanitwandler (2)\nGürtel der fast perfekten Unverwundbarkeit\nWird beim Anlegen gebunden\nTaille Stoff\n201 Rüstung\n+21 Ausdauer\n43 Rüstung\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst\n(350)\nBenutzen: Schützt Euch mit einem Energieschild, das 8 Sek. lang 4000 Schaden aufhält. (5 Min Abklingzeit)\n\"Der Schutz ist nicht immer wirksam. In SELTENEN Fällen kann der Träger zusätzlichen Schaden erleiden.\"" }
