entries[31077] = { ["name"] = "Kronenreif der grünen Flamme", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nKhoriumbarren (20), Urleben (20), Talasit (2), Quecksilberadamantit (5)\nKronenreif der grünen Flamme\nWird beim Anlegen gebunden\nKopf Stoff\n306 Rüstung\n+36 Ausdauer\n+40 Intelligenz\nHaltbarkeit 100 / 100\n70\nAnlegen: Chance bei erfolgreichem Zauberwirken im Verlauf von 10 Sek. 90 Mana wiederherzustellen. (Procchance: 75%, 25s Abklingzeit)" }
entries[31078] = { ["name"] = "Reif der arkanen Macht", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nTeufelsstahlbarren (20), Urmana (20), Stern der Elune (2), Quecksilberadamantit (5)\nReif der arkanen Macht\nWird beim Anlegen gebunden\nKopf Stoff\n306 Rüstung\n+39 Ausdauer\n+27 Intelligenz\n+27 Willenskraft\nHaltbarkeit 100 / 100\n70\nAnlegen: Chance von 2%, bei erfolgreichem Zauberwirken die Zaubermacht 15 Sek. lang um bis zu 120 zu erhöhen. (Procchance: 2%)" }
entries[31079] = { ["name"] = "Figur - Teufelsstahleber", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nTeufelsstahlbarren (8), Blutgranat (2), Urerde (4)\nFigur - Teufelsstahleber\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n70\nBenötigt Juwelenschleifen\n(370)\nAnlegen: Erhöht die Angriffskraft um 68.\nBenutzen: Beschwört einen Teufelsstahleber, der 30 Sek. lang für Euch kämpft. (5 Min Abklingzeit)" }
entries[31080] = { ["name"] = "Figur - Dämmersteinkrebs", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nKhoriumbarren (4), Dämmerstein (2), Golddraenit (4)\nFigur - Dämmersteinkrebs\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n70\nBenötigt Juwelenschleifen\n(370)\nAnlegen: Erhöht Eure Ausweichwertung um 32.\nBenutzen: Erhöht die Ausweichwertung 20 Sek. lang um 125. (2 Min Abklingzeit)" }
entries[31081] = { ["name"] = "Figur - Lebendige Rubinschlange", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nTeufelsstahlbarren (2), Lebendiger Rubin (2), Urfeuer (4)\nFigur - Lebendige Rubinschlange\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+33 Ausdauer\n+23 Intelligenz\n70\nBenötigt Juwelenschleifen\n(370)\nBenutzen: Erhöht die Zaubermacht 20 Sek. lang um 150. (5 Min Abklingzeit)" }
entries[31082] = { ["name"] = "Figur - Talasiteule", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nEterniumbarren (2), Talasit (2), Urmana (4)\nFigur - Talasiteule\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+36 Willenskraft\n70\nBenötigt Juwelenschleifen\n(370)\nBenutzen: Stellt im Verlauf von 12 Sek. insgesamt 900 Mana wieder her. (5 Min Abklingzeit)" }
entries[31083] = { ["name"] = "Figur - Nachtaugenpanther", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nGehärteter Adamantitbarren (6), Nachtauge (2), Urschatten (2)\nFigur - Nachtaugenpanther\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n70\nBenötigt Juwelenschleifen\n(370)\nAnlegen: Erhöht die Angriffskraft um 54.\nBenutzen: Erhöht die Angriffskraft 12 Sek. lang um 320. (3 Min Abklingzeit)" }
