entries[31225] = { ["name"] = "Schimmerndes Gefäß", ["text"] = "40 Meter Reichweite\nWirken in 10 sek.\nBenutzt die im Gefäß gespeicherte Magie, um Sangrias Stillstreich ins Leben zurück zu holen." }
entries[31228] = { ["name"] = "Von der Schippe springen", ["text"] = "Gewährt eine Chance von 33%, dass ein Angriff, der Euch normalerweise töten würde, Eure Gesundheit lediglich auf 10% Eurer maximalen Gesundheit verringert und Euer erlittener Schaden 3 Sek. lang um 80% verringert wird. Dieser Effekt kann nur ein Mal alle 90 Sek. auftreten." }
