entries[31595] = { ["name"] = "Arkanblitz", ["text"] = "30 Meter Reichweite\nWirken in 2.5 sek.\nFügt dem Ziel 28 to 42 Arkanschaden zu." }
entries[31596] = { ["name"] = "Gegenzauber", ["text"] = "100 Mana 30 Meter Reichweite\nSofort\nKontert den Zauber eines Feindes und verhindert 6 Sek. lang, dass der Feind den gleichen Zauber noch einmal wirkt. Führt zu einem hohen Maß an Bedrohung." }
entries[31598] = { ["name"] = "Feuerregen", ["text"] = "50 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 9 sek.)\nLässt einen Schmelzregen niedergehen, der alle Feinde im ausgewählten Gebiet verbrennt und ihnen 9 Sek. lang alle 3 Sek. Feuerschaden zufügt." }
entries[31599] = { ["name"] = "Netherwandeln" }
entries[31600] = { ["name"] = "Gruftskarabäen", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nBeschwört mehrere Gruftskarabäen, die das Ziel des Zaubernden angreifen." }
entries[31601] = { ["name"] = "Gruftskarabäen", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nBeschwört mehrere Gruftskarabäen, die das Ziel des Zaubernden angreifen." }
entries[31602] = { ["name"] = "Gruftskarabäen", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nBeschwört mehrere Gruftskarabäen, die das Ziel des Zaubernden angreifen." }
entries[31604] = { ["name"] = "Arkanschwäche", ["text"] = "30 Meter Reichweite\nWirken in 1 sek.\nVerringert die Intelligenz des Ziels 1 Min. lang um 5. Bis zu 10-mal stapelbar." }
entries[31605] = { ["name"] = "Netherwandeln" }
entries[31606] = { ["name"] = "Sturmkrähenamulett", ["text"] = "20 Meter Reichweite\nSofort\nErlaubt es Ysiel, Euch in eine durch sie kontrollierte Sturmkrähe zu verwandeln." }
entries[31607] = { ["name"] = "Krankheitswolke", ["text"] = "Sofort\nEine faulige Krankheitswolke umgibt den Zaubernden, die nahen Gegnern Naturschaden zufügt." }
